 } } \right| = 0$$


$$ \Rightarrow \left[ {1 + {{\left( { - 1} \right)}^{n + 2}}} \right]\left( {a + c} \right)\left( {2b + 1 + 2b - 1} \right) = 0$$


$$ \Rightarrow 4b\left( {a + c} \right)\left[ {1 + {{\left( { - 1} \right)}^{n + 2}}} \right] = 0$$


