   1  \cr 

 } } \right)$$ and $$A\left( {\matrix{
   0  \cr 
   0  \cr 
   1  \cr 

 } } \right) = \left( {\matrix{
   1  \cr 
   1  \cr 
   2  \cr 

 } } \right)$$.
If $$X = {({x_1},{x_2},{x_3})^T}$$ and I is an identity matrix of order 3, then the system $$(A - 2I)X = \left( {\matrix{
   4  \cr 
   1  \cr 
   1  \cr 

 } } \right)$$ has :

explanation:
Let $$A = \left[ {\matrix{
   a & b & c  \cr 
   d & e & f  \cr 
   g & h & i  \cr 

 } } \right]$$
$$A = \left[ {\matrix{
   1  \cr 
   1  \cr 
   0  \cr 

 } } \right] = \left[ {\matrix{
   1  \cr 
   1  \cr 
   0  \cr 

 } } \right] \Rightarrow \left[ {\matrix{
   a & b & c  \cr 
   d & e & f  \cr 
   g & h & i  \cr 

 } } \right]\left[ {\matrix{
   1  \cr 
   1  \cr 
   0  \cr 

 } } \right] = \left[ {\matrix{
   1  \cr 
   1  \cr 
   0  \cr 

 } } \right] \Rightarrow \matrix{
   {a + b = 1}  \cr 
   {d + e = 1}  \cr 
   {g + h = 0}  \cr 

 } $$
$$A = \left[ {\matrix{
   1  \cr 
   0  \cr 
   1  \cr 

 } } \right] = \left[ {\matrix{
   { - 1}  \cr 
   0  \cr 
   1  \cr 

 } } \right] \Rightarrow \left[ {\matrix{
   a & b & c  \cr 
   d & e & f  \cr 
   g & h & i  \cr 

 } } \right]\left[ {\matrix{
   1  \cr 
   0  \cr 
   1  \cr 

 } } \right] = \left[ {\matrix{
   { - 1}  \cr 
   0  \cr 
   1  \cr 

 } } \right] \Rightarrow \matrix{
   {a + c =  - 1}  \cr 
   {d + f = 1}  \cr 
   {g + i = 0}  \cr 

 } $$
$$A = \left[ {\matrix{
   0  \cr 
   0  \cr 
   1  \cr 

 } } \right] = \left[ {\matrix{
   1  \cr 
   1  \cr 
   2  \cr 

 } } \right] \Rightarrow \left[ {\matrix{
   a & b & c  \cr 
   d & e & f  \cr 
   g & h & i  \cr 

 } } \right]\left[ {\matrix{
   0  \cr 
   0  \cr 
   1  \cr 

 } } \right] = \left[ {\matrix{
   1  \cr 
   1  \cr 
   2  \cr 

 } } \right] \Rightarrow \matrix{
   {c = 1}  \cr 
   {f = 1}  \cr 
   {i = 2}  \cr 

 } $$
Solving will get
$$a =  - 2,\,b = 3,\,c = 1,\,d =  - 1,\,e = 2,\,f = 1,\,g =  - 1,\,h = 1,\,i = 2$$
$$A = \left[ {\matrix{
   { - 2} & 3 & 1  \cr 
   { - 1} & 2 & 1  \cr 
   { - 1} & 1 & 2  \cr 

 } } \right] \Rightarrow A = 2I = \left[ {\matrix{
   { - 4} & 3 & 1  \cr 
   { - 1} & 0 & 1  \cr 
   { - 1} & 1 & 0  \cr 

 } } \right]$$
$$(A - 2I)x = \left[ {\matrix{
   4  \cr 
   1  \cr 
   1  \cr 

 } } \right]$$
$$ \Rightarrow  - 4{x_1} + 3{x_2} + {x_3} = 4$$ ..... (i)
$$ - {x_1} + {x_3} = 1$$ ...... (ii)
$$ - {x_1} + {x_2} = 1$$ ...... (iii)
So 3(iii) + (ii) = (i)
$$\therefore$$ Infinite solution

question:
Let $$A = \left[ {\matrix{
   0 & { - 2}  \cr 
   2 & 0  \cr 

 } } \right]$$. If M and N are two matrices given by $$M = \sum\limits_{k = 1}^{10} {{A^{2k}}} $$ and $$N = \sum\limits_{k = 1}^{10} {{A^{2k - 1}}} $$ then MN2 is :

Let $$S = \left\{ {\left( {\matrix{
   { - 1} & a  \cr 
   0 & b  \cr 

 } } \right);a,b \in \{ 1,2,3,....100\} } \right\}$$ and let $${T_n} = \{ A \in S:{A^{n(n + 1)}} = I\} $$. Then the number of elements in $$\bigcap\limits_{n = 1}^{100} {{T_n}} $$ is ___________.

explanation:
$$
\begin{aligned}
&\mathrm{A}=\left[\begin{array}{cc}
-1 & \mathrm{a} \\\\
0 & \mathrm{~b}
\end{array}\right] \\\\
&\mathrm{A}^2=\left[\begin{array}{cc}
-1 & \mathrm{a} \\\\
0 & \mathrm{~b}
\end{array}\right]\left[\begin{array}{cc}
-1 & \mathrm{a} \\\\
0 & \mathrm{~b}
\end{array}\right] \\\\
&=\left[\begin{array}{cc}
1 & -\mathrm{a}+\mathrm{ab} \\\\
0 & \mathrm{~b}^2
\end{array}\right] \\\\
&\therefore \mathrm{T}_{\mathrm{n}}=\left\{\mathrm{A} \in \mathrm{S} ; \mathrm{A}^{\mathrm{n}(\mathrm{n}+1)}=\mathrm{I}\right\}
\end{aligned}
$$


$\therefore$ b must be equal to 1


$\therefore$ In this case $\mathrm{A}^2$ will become identity matrix and a can take any value from 1 to 100


$\therefore$ Total number of common element will be 100 .

question:
Let $$A = \left[ {\matrix{
   1 & { - 2} & \alpha   \cr 
   \alpha  & 2 & { - 1}  \cr 

 } } \right]$$ and $$B = \left[ {\matrix{
   2 & \alpha   \cr 
   { - 1} & 2  \cr 
   4 & { - 5}  \cr 

 } } \right],\,\alpha  \in C$$. Then the absolute value of the sum of all values of $$\alpha$$ for which det(AB) = 0 is :

explanation:
Given,
$$A = \left[ {\matrix{
   1 & { - 2} & \alpha   \cr 
   \alpha  & 2 & { - 1}  \cr 

 } } \right]$$
and $$B = \left[ {\matrix{
   2 & \alpha   \cr 
   { - 1} & 2  \cr 
   4 & { - 5}  \cr 

 } } \right]$$
$$AB = \left[ {\matrix{
   1 & { - 2} & \alpha   \cr 
   \alpha  & 2 & { - 1}  \cr 

 } } \right]\left[ {\matrix{
   2 & \alpha   \cr 
   { - 1} & 2  \cr 
   4 & { - 5}  \cr 

 } } \right]$$
$$ = \left[ {\matrix{
   {4 + 4\alpha } & { - 4\alpha  - 4}  \cr 
   {2\alpha  - 6} & {{\alpha ^2} + 9}  \cr 

 } } \right]$$
Given,
$$|AB| = 0$$
$$\therefore$$ $$\left| {\matrix{
   {4 + 4\alpha } & { - 4\alpha  - 4}  \cr 
   {2\alpha  - 6} & {{\alpha ^2} + 9}  \cr 

 } } \right| = 0$$
$$ \Rightarrow (4\alpha  + 4)\left| {\matrix{
   1 & { - 1}  \cr 
   {2\alpha  - 6} & {{\alpha ^2} + 9}  \cr 

 } } \right| = 0$$
$$ \Rightarrow (4\alpha  + 4)({\alpha ^2} + 9 + 2\alpha  - 6) = 0$$
$$ \Rightarrow (4\alpha  + 4)({\alpha ^2} + 2\alpha  + 3) = 0$$
$$\therefore$$ $$\alpha  -  =  - 1$$
or $${\alpha ^2} + 2\alpha  + 3 = 0$$
$${\alpha _1} + {\alpha _2} =  - 2$$
$$\therefore$$ Sum of all values of $$\alpha  =  - 1 - 2 =  - 3$$
$$\therefore$$ Absolute value of $$\alpha  = | - 3| = 3$$

$$A = \left[ {\matrix{
   1 & 0 & 0  \cr 
   0 & 1 & 0  \cr 
   0 & 0 & 1  \cr 

 } } \right] + \left[ {\matrix{
   0 & a & a  \cr 
   0 & 0 & b  \cr 
   0 & 0 & 0  \cr 

 } } \right] = I + B$$
$${B^2} = \left[ {\matrix{
   0 & a & a  \cr 
   0 & 0 & b  \cr 
   0 & 0 & 0  \cr 

 } } \right] + \left[ {\matrix{
   0 & a & a  \cr 
   0 & 0 & b  \cr 
   0 & 0 & 0  \cr 

 } } \right] = \left[ {\matrix{
   0 & 0 & {ab}  \cr 
   0 & 0 & 0  \cr 
   0 & 0 & 0  \cr 

 } } \right]$$
$${B^3} = 0$$
$$\therefore$$ $${A^n} = {(1 + B)^n} = {}^n{C_0}I + {}^n{C_1}B + {}^n{C_2}{B^2} + {}^n{C_3}{B^3} + \,\,....$$
$$ = \left[ {\matrix{
