&amp; -\frac{\mathrm{GMm}}{2 \mathrm{R}}+0=-\frac{\mathrm{GMm}}{\mathrm{R}}+\frac{1}{2} \mathrm{mv}^2 \\\\
&amp; \frac{\mathrm{GMm}}{2 \mathrm{R}}=\frac{1}{2} \mathrm{mv}^2 \\\\
&amp; \mathrm{v}=\sqrt{\frac{\mathrm{GM}}{\mathrm{R}}}=\sqrt{\mathrm{gR}}
\end{aligned}
$$

$$\begin{aligned}
& \mathrm{V}_{\text {escape }}=\sqrt{\frac{2 \mathrm{GM}}{\mathrm{R}}} \\
& \mathrm{V}_{\text {planet }}=\sqrt{\frac{2 \mathrm{GM}}{\mathrm{R}}}=\mathrm{V} \\
& \mathrm{V}_{\text {Moon }}=\sqrt{\frac{2 \mathrm{GM} \times 16}{144 \mathrm{R}}}=\frac{1}{3} \sqrt{\frac{2 \mathrm{GM}}{\mathrm{R}}} \\
& \mathrm{V}_{\text {Moon }}=\frac{\mathrm{V}_{\text {Planet }}}{3}=\frac{\mathrm{V}}{3}
\end{aligned}$$

Acceleration due to gravity g' $$=\frac{g}{4}$$
$$\begin{aligned}
& \mathrm{T}=2 \pi \sqrt{\frac{4 \ell}{\mathrm{g}}} \\
& \mathrm{T}=2 \pi \sqrt{\frac{4 \times 4}{\mathrm{~g}}} \\
& \mathrm{~T}=2 \pi \frac{4}{\pi}=8 \mathrm{~s}
\end{aligned}$$

