&=\frac{720 \times 340}{360}=680 \mathrm{~Hz}
\end{aligned}
$$

$A_{R}=\sqrt{A_{1}^{2}+A_{2}^{2}+2 A_{1} A_{2} \cos \phi}$



$$
\begin{aligned}
& 8=\sqrt{8^{2}+8^{2}+2 \times 8 \times 8 \cos \phi} \\\\
& \Rightarrow \cos \phi=-\frac{1}{2} \\\\
& \Rightarrow \phi=120^{\circ}
\end{aligned}
$$

